function drawVoiceFields(){cancelAnimationFrame(voiceFrame);fieldCleanups.forEach(f=>f());fieldCleanups=[];const canvases=[...document.querySelectorAll('canvas.voicefield')];if(!canvases.length)return;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const points=[];for(let i=0;i<520;i++){const y=1-2*(i+.5)/520,r=Math.sqrt(1-y*y),a=i*2.399963;points.push([Math.cos(a)*r,y,Math.sin(a)*r])}const glRenderers=new Map();for(let i=0;i<canvases.length;i++){let c=canvases[i],draw=fluidField(c);if(!draw&&c.addyHadGL){const replacement=c.cloneNode(false);c.replaceWith(replacement);c=replacement;canvases[i]=c}glRenderers.set(c,draw)}const start=performance.now();function draw(now){const dt=(now-start)/1000,active=['listening','speaking'].includes(view.voice);for(const canvas of canvases){const gpu=glRenderers.get(canvas);if(gpu){gpu(reduce?2500:now);continue}const c=canvas.getContext('2d');if(!c)continue;c.clearRect(0,0,400,400);const angle=reduce?.3:dt*.14,breath=reduce?1:1+Math.sin(dt*1.3)*.018;const sorted=points.map(([x,y,z])=>[x*Math.cos(angle)+z*Math.sin(angle),y,z*Math.cos(angle)-x*Math.sin(angle)]).sort((a,b)=>a[2]-b[2]);for(const [x,y,z] of sorted){const depth=(z+1)/2,scale=125*breath*(active?1+Math.sin(dt*3+y*4)*.025:1),opacity=.15+depth*.72,radius=1+depth*1.9;c.beginPath();c.arc(200+x*scale,200+y*scale,radius,0,Math.PI*2);c.fillStyle=canvas.closest('.voice-stage')?`rgba(${Math.round(150+depth*67)},${Math.round(175+depth*48)},${Math.round(155+depth*40)},${opacity})`:`rgba(31,91,73,${opacity})`;c.fill()}}if(!reduce)voiceFrame=requestAnimationFrame(draw)}draw(performance.now())}
