function intakeQuestions(){return s.type==='business'?[tr('What is your full name?','ما اسمك الكامل؟','Quel est votre nom complet ?'),tr('What business are you building?','ما النشاط الذي تريد تأسيسه؟','Quelle activité souhaitez-vous créer ?'),tr('Where are you in the setup journey?','في أي مرحلة من تأسيس مشروعك أنت؟','Où en êtes-vous dans votre installation ?'),tr('What timeline and budget are you planning for?','ما الموعد والميزانية التي تخطط لها؟','Quel calendrier et quel budget prévoyez-vous ?'),tr('Tell me how your business will work.','حدثني عن طريقة عمل مشروعك.','Décrivez le fonctionnement de votre entreprise.'),tr('What help would make the biggest difference?','ما المساعدة التي ستحدث أكبر فرق؟','Quelle aide vous serait la plus utile ?')]:[tr('What is your full name?','ما اسمك الكامل؟','Quel est votre nom complet ?'),tr('How old are you?','كم عمرك؟','Quel âge avez-vous ?'),tr('How do you describe your gender?','كيف تصف جنسك؟','Comment décrivez-vous votre genre ?'),tr('Where are you in your Abu Dhabi journey?','أين وصلت في رحلتك إلى أبوظبي؟','Où en êtes-vous dans votre arrivée à Abu Dhabi ?'),tr('What do you love, and what’s not for you?','ما الذي تحبه وما الذي لا يناسبك؟','Qu’aimez-vous, et que préférez-vous éviter ?'),tr('Who’s joining you, and what would help you settle?','من سيرافقك وما الذي يساعدك على الاستقرار؟','Qui vous accompagne, et comment faciliter votre arrivée ?')]}
function onboardingPrompt(){return intakeQuestions()[intakeStep()]||tr('Your first profile is ready to review.','ملفك الأول جاهز للمراجعة.','Votre premier profil est prêt à vérifier.')}
function intakeExample(){const n=intakeStep();if(n<4)return '';return s.type==='business'?(n===4?tr('For example: a small café serving karak and sandwiches, with six tables and two staff.','مثلًا: مقهى صغير يقدم الكرك والسندويشات، بست طاولات وموظفين.','Exemple : un petit café proposant du karak et des sandwichs, six tables et deux employés.'):tr('For example: choosing the right activities, premises approvals, suppliers, or a banking checklist.','مثلًا: اختيار الأنشطة المناسبة أو موافقات الموقع أو الموردين أو خطوات فتح حساب مصرفي.','Exemple : activités autorisées, approbations du local, fournisseurs ou démarches bancaires.')):(n===4?tr('For example: Japanese food, jazz and comedy; I prefer quiet cafés and avoid crowded malls.','مثلًا: الطعام الياباني والجاز والكوميديا؛ أفضل المقاهي الهادئة وأتجنب المراكز المزدحمة.','Exemple : cuisine japonaise, jazz et comédie ; cafés calmes plutôt que centres bondés.'):tr('For example: with my partner and an elderly parent; step-free outings and moving help matter. No private medical details needed.','مثلًا: مع شريكي وأحد والديّ المسنين؛ تهمني الأماكن دون درج ومساعدة الانتقال. لا حاجة لتفاصيل طبية.','Exemple : avec mon conjoint et un parent âgé ; sorties accessibles et aide au déménagement, sans détails médicaux.'))}
function intakeForm(){const n=intakeStep(),p=s.profile,b=s.type==='business',input=(key,label,value='',type='text')=>`<label class="field">${label}<input data-intake="${key}" type="${type}" value="${esc(value)}" maxlength="120" required autocomplete="off"></label>`,select=(key,label,options,value)=>`<label class="field">${label}<select data-intake="${key}" required><option value="">${tr('Choose one','اختر','Choisir')}</option>${options.map(([v,l])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${l}</option>`).join('')}</select></label>`;let fields='';if(n===0)fields=input('name',tr('Full name','الاسم الكامل','Nom complet'),p.name||'');if(!b&&n===1)fields=input('ageRange',tr('Age, or “Prefer not to say”','العمر أو «أفضل عدم الإفصاح»','Âge, ou « Je préfère ne pas répondre »'),p.ageRange||'');if(!b&&n===2)fields=select('gender',tr('Gender','الجنس','Genre'),[['Woman',tr('Woman','امرأة','Femme')],['Man',tr('Man','رجل','Homme')],['Self-described',tr('Self-described','وصف ذاتي','Autre description')],['Prefer not to say',tr('Prefer not to say','أفضل عدم الإفصاح','Je préfère ne pas répondre')]],p.gender);if(b&&n===1)fields=input('sector',tr('Business activity','النشاط التجاري','Activité'),p.sector||'')+`<p class="small muted">${tr('Café, printing, technology, consulting…','مقهى، طباعة، تقنية، استشارات…','Café, imprimerie, technologie, conseil…')}</p>`;if(b&&n===2)fields=select('setupStage',tr('Stage','المرحلة','Étape'),[['Exploring',tr('Exploring an idea','أستكشف فكرة','J’explore une idée')],['Setting up',tr('Ready to set up','مستعد للتأسيس','Prêt à créer')],['Existing business',tr('Existing business / expanding','مشروع قائم / توسع','Entreprise existante / expansion')]],p.setupStage)+select('setupRoute',tr('Setup route','مسار التأسيس','Implantation'),[['Not sure',tr('Not sure yet','غير متأكد بعد','À déterminer')],['Mainland',tr('Mainland','البر الرئيسي','Hors zone franche')],['Free zone',tr('Free zone','منطقة حرة','Zone franche')],['Existing licence',tr('Existing licence','رخصة قائمة','Licence existante')]],p.setupRoute)+input('area',tr('Preferred area or “Not sure”','المنطقة المفضلة أو «غير متأكد»','Quartier souhaité ou « Indécis »'),p.area||'');if(b&&n===3)fields=input('timeline',tr('Target opening / move date','موعد الافتتاح أو الانتقال المستهدف','Date d’ouverture / arrivée'),p.timeline||'')+input('budget',tr('Setup budget in AED, or “Not decided”','ميزانية التأسيس بالدرهم أو «لم أحدد»','Budget en AED ou « À définir »'),p.budget||'');if(!b&&n===3)fields=select('moveStatus',tr('My status','حالتي','Ma situation'),[['Planning',tr('Planning to move','أخطط للانتقال','Je prévois de venir')],['Moved',tr('Already in Abu Dhabi','أنا في أبوظبي بالفعل','Je suis déjà à Abu Dhabi')]],p.moveStatus)+input('moveDetail',tr('When are you moving, or which area do you live in?','متى ستنتقل أو في أي منطقة تقيم؟','Quand arrivez-vous, ou dans quel quartier habitez-vous ?'),p.moveStatus==='Moved'?p.area||'':p.timeline||'');return `<form id="intakeform">${fields}<p class="small muted">${tr('A clear answer helps us continue. You can choose not to disclose age or gender.','إجابة واضحة تساعدنا على المتابعة. يمكنك عدم الإفصاح عن العمر أو الجنس.','Répondez pour continuer. Vous pouvez ne pas préciser votre âge ou votre genre.')}</p><button class="button intake-continue" type="submit">${t('next')}${icon('send')}</button></form>`}
function onboardingScene(){const step=intakeStep();return `<main class="cinema intake-app"><div class="cinema-top"><button class="textbutton" data-do="intakeback">${t('back')}</button><span class="eyebrow">${Math.min(step+1,6)} / 6</span><button class="textbutton" data-do="intakeprofile">${t('profile')} · ${progressScore()}</button></div><progress class="step-progress" max="6" value="${step}"></progress><div class="onboard-columns"><section class="cinema-center"><div class="cinema-orbit">${orb()}</div><div class="cinema-question"><h1>${esc(onboardingPrompt())}</h1><p class="intake-example">${esc(intakeExample())}</p></div>${step<4?intakeForm():step<6?`<div class="intake-feedback" role="status">${view.busy?tr('Building your profile…','جارٍ بناء ملفك…','Création de votre profil…'):esc(view.reply||tr('A short answer is enough. About 20–30 seconds.','إجابة قصيرة تكفي، حوالي 20–30 ثانية.','Une réponse de 20 à 30 secondes suffit.'))}</div><details class="story-transcript" ${view.transcript?'':'hidden'}><summary>${tr('Your words','كلماتك','Vos mots')}</summary><p data-live-transcript>${esc(view.transcript||'')}</p></details><div class="cinema-bottom">${inputDock()}</div>`:`<div class="cinema-bottom"><button class="button" data-do="finish">${tr('Review my profile','راجع ملفي','Vérifier mon profil')}</button></div>`}</section><aside class="profile-unfolding"><div class="profile-unfolding-title"><span>${tr('Your profile, taking shape','ملفك يتشكل','Votre profil prend forme')}</span><span class="points">${progressScore()} ${tr('points','نقطة','points')}</span></div><progress max="80" value="${progressScore()}"></progress><div class="profile-facts">${Object.entries(s.profile).filter(([k,v])=>k!=='nameConfirmed'&&v&&(Array.isArray(v)?v.length:true)).map(([k,v])=>`<div><span class="small muted">${esc(profileLabel(k))}</span><p>${esc(Array.isArray(v)?v.map(lx).join(' · '):lx(v))}</p></div>`).join('')||`<p class="muted">${tr('What you share will appear here.','سيظهر ما تشاركه هنا.','Ce que vous partagez apparaîtra ici.')}</p>`}</div><button class="textbutton" data-do="profile">${tr('Correct my profile','صحح ملفي','Corriger mon profil')}</button><p class="small muted">${tr('Extracted from your answers. Please correct anything that feels wrong. Unknown preferences stay unknown.','مستخلص من إجاباتك. صحح أي معلومة غير دقيقة. لا نخمن التفضيلات المجهولة.','Extrait de vos réponses. Corrigez les erreurs ; les goûts inconnus restent inconnus.')}</p><div class="reward-preview"><strong>${tr('Rewards preview','معاينة المكافآت','Aperçu des récompenses')}</strong><p class="${progressScore()>=10?'unlocked':''}">10 ${tr('points → 10% at Dune Table','نقاط ← خصم 10٪ في Dune Table','points → 10 % chez Dune Table')}</p><p class="${progressScore()>=40?'unlocked':''}">40 ${tr('points → 40% at Oasis Mall','نقطة ← خصم 40٪ في Oasis Mall','points → 40 % chez Oasis Mall')}</p><small>${tr('Fictional demo partners and offers. Not redeemable.','شركاء وعروض خيالية للعرض فقط، غير قابلة للاسترداد.','Partenaires et offres fictifs de démonstration. Non utilisables.')}</small></div></aside></div></main>`}

function profileReview(){return `<main class="profile-review"><div class="eyebrow muted">${tr('A FIRST PICTURE. ALWAYS EDITABLE.','صورة أولى، قابلة للتعديل دائمًا','UNE PREMIÈRE IMAGE, TOUJOURS MODIFIABLE')}</div><h1>${tr('Does this feel like you?','هل يشبهك هذا؟','Est-ce que cela vous ressemble ?')}</h1><p class="muted">${tr('Confirm what’s right. Change what isn’t. This is the starting point for your Addy.','أكد ما هو صحيح وعدّل ما يحتاج إلى تعديل. هذه نقطة البداية مع Addy.','Confirmez ce qui est juste, modifiez le reste. C’est le point de départ de votre Addy.')}</p>${nameConfirmation()}<div class="review-grid">${Object.entries(s.profile).filter(([k,v])=>k!=='nameConfirmed'&&v&&(Array.isArray(v)?v.length:true)).map(([k,v])=>`<article><span class="small muted">${esc(profileLabel(k))}</span><h3>${esc(Array.isArray(v)?v.map(lx).join(' · '):lx(v))}</h3></article>`).join('')||`<p>${tr('No preferences yet. You can keep talking or explore starter ideas.','لا توجد تفضيلات بعد. تابع الحديث أو استكشف أفكار البداية.','Pas encore de préférences. Continuez à discuter ou découvrez les premières idées.')}</p>`}</div><label class="account-consent"><input type="checkbox" id="accountconsent" ${s.ownerSummaryConsent?'checked':''}><span>${tr('Save an account summary with Addy: my name, signed-in email, account type, business sector, selected interests, and basic app actions. Addy owners can view this summary. No audio, transcripts, age, gender, budgets or medical details. Optional.','احفظ ملخص حساب لدى Addy: اسمي وبريد تسجيل الدخول ونوع الحساب وقطاع النشاط والاهتمامات المختارة وإجراءات التطبيق الأساسية. يمكن لمالكي Addy مشاهدة الملخص. دون صوت أو محادثات أو عمر أو جنس أو ميزانيات أو بيانات طبية. اختياري.','Enregistrer un résumé chez Addy : nom, e-mail de connexion, type de compte, secteur, centres d’intérêt et actions de base. Visible aux propriétaires Addy. Aucun audio, transcription, âge, genre, budget ou donnée médicale. Facultatif.')}</span></label><div class="actions"><button class="button" data-do="approveprofile">${t('finish')}</button><button class="button outline" data-go="onboard">${tr('Keep talking','لنكمل الحديث','Continuer à parler')}</button><button class="textbutton" data-do="profile">${t('edit')}</button></div></main>`}
function assistantScene(){return `<main class="assistant-app"><div class="assistant-top"><button class="textbutton" data-go="discover">${t('back')}</button><h1>${tr('Talk to Addy','تحدث إلى Addy','Parler à Addy')}</h1><button class="textbutton" data-do="newchat">${tr('New','جديد','Nouveau')}</button></div><section class="assistant-scroll"><div class="assistant-mini-orb">${orb()}</div>${view.transcript?`<p class="user-note" data-live-transcript>${esc(view.transcript)}</p>`:''}<div class="assistant-answer" role="status"><h2>${esc(view.reply||(view.busy?tr('Checking your request and constraints…','أراجع طلبك وقيودك…','Je vérifie votre demande et vos contraintes…'):tr('What would you like to get done?','ماذا ترغب في إنجازه؟','Que souhaitez-vous accomplir ?')))}</h2></div>${view.resultCards?.length?`<div class="assistant-results">${view.resultCards.map(p=>`<button class="voice-result" data-detail="${esc(p.id)}">${p.img?`<img src="${safeURL(p.img)?esc(p.img):'assets/'+esc(p.img)}" alt="${esc(p.name)}">`:''}<div><h3>${esc(p.name)}</h3><p>${esc(p.area)}</p></div></button>`).join('')}</div>`:''}${s.plan.length?`<button class="button soft" data-go="plan">${t('plan')} · ${s.plan.length} ${tr('steps','خطوات','étapes')}</button>`:''}${view.sources?.length?`<div class="answer-sources">${view.sources.map(x=>`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title||t('source'))}</a>`).join('')}</div>`:''}</section><div class="assistant-fixed-dock">${inputDock()}</div></main>`}

function voiceScreen(){const q=currentQuestion(),isOn=s.screen==='onboard';const question=view.reply||(isOn?(q?.text||tr('I’m getting a picture of your Abu Dhabi.','بدأت أتعرف على أبوظبي التي تناسبك.','Je commence à cerner votre Abu Dhabi.')):tr('What shall we make happen?','ماذا نخطط له اليوم؟','Que fait-on aujourd’hui ?'));return `<main class="voice-layout"><section class="voice-stage ${view.resultCards?.length?'has-results':''}"><div class="voice-heading"><button class="textbutton" data-go="${isOn?'welcome':'discover'}">${t('back')}</button><button class="textbutton" data-do="${isOn?'restart':'newchat'}">${isOn?tr('Start over','ابدأ من جديد','Recommencer'):tr('New chat','محادثة جديدة','Nouvel échange')}</button><span class="pill">${api.configured?t('live'):t('demo')}</span></div><div class="voice-body">${orb()}<p class="previous" data-live-transcript>${esc(view.transcript||'')}</p><div class="mobile-reward small">${progressScore()} ${tr('demo exploration points · no cash value','نقاط استكشاف تجريبية · دون قيمة نقدية','points découverte de démo · sans valeur monétaire')}</div><h2 class="${view.reply?'answer':''}">${esc(question)}</h2>${view.pendingName?`<div class="name-confirm"><label for="heardname">${tr('Did I get your name right? Edit it if needed.','هل التقطت اسمك بشكل صحيح؟ عدّله إن لزم.','Ai-je bien compris votre nom ? Corrigez-le si besoin.')}</label><input id="heardname" value="${esc(view.pendingName)}" maxlength="100"><div><button class="button" id="confirmname">${tr('Yes, that’s my name','نعم، هذا اسمي','Oui, c’est mon nom')}</button><button class="textbutton" id="skipname">${tr('Skip for now','لاحقًا','Plus tard')}</button></div></div>`:''}<p class="question-sub">${isOn?esc(q?.sub||tr('We can keep exploring, or turn what I’ve learned into a first plan.','يمكننا مواصلة الحديث أو تحويل ما تعلمته إلى خطة أولى.','Une conversation, une expérience plus personnelle.')):tr('Food, friends, a new business. I’m listening.','طعام، أصدقاء، مشروع جديد. أنا أستمع.','Un repas, des amis, un projet. Je vous écoute.')}</p>${view.resultCards?.length?`<div class="voice-results">${view.resultCards.slice(0,1).map(p=>`<article class="voice-result">${p.img?`<img src="${safeURL(p.img)?esc(p.img):'assets/'+esc(p.img)}" alt="${esc(localPlace(p).name)}" referrerpolicy="no-referrer">`:''}<div><h3>${esc(localPlace(p).name)}</h3><p>${esc(localPlace(p).area)}</p><button class="button" data-detail="${esc(p.id)}">${tr('Explore this option','استكشف هذا الخيار','Explorer cette option')}</button></div></article>`).join('')}<button class="textbutton" data-go="discover" style="color:var(--cream)">${tr('See all options','شاهد كل الخيارات','Voir toutes les options')}</button></div>`:''}${isOn&&!api.configured&&q?.options?.length?`<div class="voice-options">${q.options.map(([value,label])=>`<button class="chip" data-answer="${value}">${label}</button>`).join('')}</div>`:''}${!q&&isOn&&!api.configured?`<button class="button light" style="margin-top:25px" data-do="finish">${t('finish')}</button>`:''}</div>${s.plan.length?`<div class="actions" style="justify-content:center;padding:0 22px"><button class="button light" data-go="plan">${t('plan')}</button><button class="textbutton" data-go="discover" style="color:var(--cream)">${t('discover')}</button></div>`:''}${view.sources?.length?`<div style="padding:0 25px 20px;text-align:center">${view.sources.map(x=>`<a class="small" style="display:inline-block;margin:5px;color:#d8e3d4" href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.title||t('source'))}</a>`).join('')}</div>`:''}<div class="voice-dock"><div class="mic-row"><button class="round" data-do="focusinput" aria-label="${t('type')}">${icon('keyboard')}</button><button class="mic-button ${view.voice==='listening'?'on':''}" ${voiceSession?.mode==='ptt'?'data-hold':'data-do="voice"'} ${view.connecting||view.busy||voiceSession?.rt?.awaitingTranscript||voiceSession?.rt?.tools?'disabled':''} aria-label="${voiceSession?.mode==='ptt'?tr('Tap to start or stop recording','اضغط لبدء التسجيل أو إيقافه','Touchez pour démarrer ou arrêter'):t('talk')}">${icon('mic')}</button><button class="round" data-do="finish" title="${t('finish')}" aria-label="${t('finish')}">${icon('check')}</button></div><p>${voiceSession?.mode==='ptt'&&view.voice==='idle'?tr('Tap to record · tap again to finish','اضغط للتسجيل ثم اضغط للإنهاء','Touchez pour enregistrer, puis pour terminer'):voiceSession?t(view.voice):t('idle')}</p>${voiceSession?`<button class="textbutton" data-do="stopvoice">${t('stopVoice')}</button>`:''}${view.audioBlocked?`<button class="button soft" data-do="enableaudio">${tr('Enable audio','تفعيل الصوت','Activer le son')}</button>`:''}<form class="composer" id="voiceform"><input id="voiceinput" placeholder="${t('requestPlaceholder')}" aria-label="${t('type')}" maxlength="1200" ${view.busy?'disabled':''}><button class="round dark" aria-label="${t('next')}" ${view.busy?'disabled':''}>${icon('send')}</button></form></div></section><aside class="understanding"><div class="progress-reward"><strong>${progressScore()} ${tr('exploration points','نقاط استكشاف','points découverte')}</strong><p>${tr('Useful preferences, a clearer picture. Demo points only; no cash or discount value.','تفضيلات مفيدة وصورة أوضح. نقاط تجريبية دون قيمة نقدية أو خصومات.','Des préférences utiles, une vision plus claire. Points de démo sans valeur monétaire.')}</p><progress max="80" value="${progressScore()}"></progress></div><span class="eyebrow muted">${tr('A little more you, with every word','أقرب إليك مع كل كلمة','Chaque mot vous ressemble un peu plus')}</span><h3>${tr('Here’s what I’m learning.','هذا ما أتعلمه عنك.','Ce que j’apprends sur vous.')}</h3><p>${tr('Nothing set in stone. You can change any of this.','يمكنك تعديل أي شيء في أي وقت.','Rien n’est figé. Vous pouvez tout modifier.')}</p><div class="memory-card"><div class="label">${t('profile')}</div><p>${esc(s.profile.name||tr('Your story starts here','حكايتك تبدأ هنا','Votre histoire commence ici'))}</p><div class="memorychips">${Object.entries(s.profile).filter(([k])=>!['name','nameConfirmed'].includes(k)).flatMap(([,v])=>Array.isArray(v)?v:[v]).map(x=>`<span>${esc(lx(x))}</span>`).join('')||`<span>${tr('You decide what to share','أنت تختار ما تشاركه','Vous choisissez quoi partager')}</span>`}</div></div><button class="textbutton" data-do="profile">${t('edit')}</button><div class="notice">${tr('Your preferences stay on this device. When AI is enabled, relevant answers are sent to OpenAI to respond.','تُحفظ تفضيلاتك على هذا الجهاز. عند تفعيل الذكاء الاصطناعي، تُرسل الإجابات ذات الصلة إلى OpenAI للرد.','Vos préférences restent sur cet appareil. Avec l’IA, les réponses pertinentes sont envoyées à OpenAI pour vous répondre.')}</div></aside></main>`}
function localPlace(p){return {...p,...(ADDY_COPY[s.lang]?.places?.[p.id]||{})}}
function catalogue(){return [...ADDY_DATA.places,...(Array.isArray(s.discoveries)?s.discoveries:[])]}
function ranked(profile=s.profile){let list=AddyRank.rank(catalogue(),profile,s.feedback,s.type);if(s.preferredIds?.length)list.sort((a,b)=>(s.preferredIds.includes(b.id)?1:0)-(s.preferredIds.includes(a.id)?1:0));return list}
function relocationServices(){const entries=[['Hotels','فنادق','Hôtels','https://visitabudhabi.ae/en/plan-your-trip/where-to-stay'],['Clinics & hospitals','عيادات ومستشفيات','Cliniques et hôpitaux','https://stem.doh.gov.ae/HFMap/'],['Typing offices','مكاتب الطباعة','Bureaux de saisie','https://www.adjd.gov.ae/en/Pages/TYPING_OFFICES.aspx'],['Government centers','مراكز حكومية','Centres administratifs','https://icp.gov.ae/customer-happiness-centers/'],['Packers & movers','شركات النقل','Déménageurs','https://u.ae/en/information-and-services/business/important-digital-services/inquire-about-licences-names-and-activities']];return `<details class="service-discovery"><summary>${tr('Your moving essentials','أساسيات انتقالك','Les essentiels de votre arrivée')}</summary>${entries.map(([en,ar,fr,url])=>`<div><button class="textbutton" data-service="${en}">${tr(en,ar,fr)} ↗</button><a class="small muted" href="${url}" target="_blank" rel="noopener">${tr('Official directory / verification','دليل رسمي / تحقق','Annuaire officiel / vérification')}</a></div>`).join('')}</details>`}
function discoveryScreen(){let list=view.filter==='Saved'?catalogue().filter(p=>s.feedback[p.id]===2):ranked().filter(p=>s.feedback[p.id]!==2&&(view.filter==='All'||p.category===view.filter));const focused=list.find(x=>x.id===view.focusCardId),p=focused||list[s.deck%Math.max(1,list.length)];return `<main class="discovery-app"><div class="deck-toolbar"><h1>${tr('Picked for you','اختيارات لك','Pour vous')}</h1><button class="textbutton" data-do="profile">${t('profile')}</button></div><div class="deck-tabs">${[['All',tr('For you','لك','Pour vous')],['Dining',tr('Food','طعام','Repas')],['Saved',tr('Saved','المحفوظات','Enregistrés')]].map(([v,l])=>`<button class="chip ${view.filter===v?'active':''}" data-filter="${v}">${l}${v==='Saved'?' · '+Object.values(s.feedback).filter(x=>x===2).length:''}</button>`).join('')}<button class="chip" data-go="journey">${tr('My journey','رحلتي','Mon parcours')}</button></div>${AddyRank.lowBudget(s.profile)?`<p class="budget-rule">${tr('Low-cost only · unverified prices are excluded','خيارات منخفضة التكلفة فقط · نستبعد الأسعار غير المؤكدة','Petit budget · prix non vérifiés exclus')}</p>`:''}${view.busy?`<p class="deck-status" role="status">${tr('Finding options that meet your preferences…','جارٍ البحث عن خيارات توافق تفضيلاتك…','Recherche selon vos préférences…')}</p>`:''}<section class="deck-zone">${p?`<article class="place-card" id="placecard"><div class="place-photo">${p.img?`<img src="${safeURL(p.img)?esc(p.img):'assets/'+esc(p.img)}" alt="${esc(localPlace(p).name)}" referrerpolicy="no-referrer">`:`<div class="photo-fallback">${icon('discover')}<span>${tr('Source-backed suggestion','اقتراح مدعوم بمصدر','Suggestion sourcée')}</span></div>`}<span class="tag">${esc(localPlace(p).category)}</span><span class="place-location">${esc(localPlace(p).area)}</span></div><div class="place-content"><h2>${esc(localPlace(p).name)}</h2><p>${esc(localPlace(p).desc)}</p><div class="fit-note">${icon('spark')}<span>${reason(p)}</span></div>${p.costEvidence?`<p class="small muted">${esc(p.costEvidence)}</p>`:''}</div><div class="card-actions"><button class="button soft" data-feedback="-1" data-id="${esc(p.id)}">${tr('Pass','تجاوز','Passer')}</button><button class="button outline" data-detail="${esc(p.id)}">${tr('Details & plan','تفاصيل وخطة','Détails et plan')}</button><button class="button" data-feedback="2" data-id="${esc(p.id)}">${tr('Save','احفظ','Garder')}</button></div></article>`:`<div class="empty-deck"><h2>${tr('Let’s find a better match.','لنجد خيارًا أنسب.','Trouvons mieux.')}</h2><p>${tr('No remaining options meet this view. Your preferences have not been relaxed.','لا توجد خيارات متبقية توافق هذه المعايير. لم نتجاهل تفضيلاتك.','Aucune option restante ne respecte ces critères. Vos préférences sont conservées.')}</p><button class="button" data-service="${AddyRank.lowBudget(s.profile)?'verified low-cost dining with published menu prices':'personalized places'}">${tr('Find more matches','ابحث عن خيارات أخرى','Trouver d’autres options')}</button></div>`}</section><div class="deck-utility"><button class="textbutton" data-do="undofeedback" ${!(s.feedbackHistory?.length||view.lastFeedback)?'disabled':''}>${tr('Undo last swipe','تراجع عن آخر اختيار','Annuler le dernier choix')}</button><span class="small muted">${tr('Left: pass · Right: save','يسار: تجاوز · يمين: حفظ','Gauche : passer · Droite : garder')}</span></div></main>`}

function reason(p){const matches=p.tags.filter(x=>[...(s.profile.interests||[]),s.profile.family,s.profile.sector].includes(x));return matches.length?tr(`A fit for your interest in ${esc(matches.map(lx).join(' + '))}.`,`يناسب اهتماماتك: ${esc(matches.map(lx).join(' + '))}.`,`Un choix lié à vos intérêts : ${esc(matches.map(lx).join(' + '))}.`):Object.keys(s.feedback).length&&p.score>0?tr('Inspired by your saved choices. You can change my direction anytime.','مستوحى من اختياراتك المحفوظة. يمكنك تغيير الاتجاه في أي وقت.','Inspiré de vos choix enregistrés. Vous pouvez me réorienter à tout moment.'):tr('A fresh possibility to explore. Tell me if it feels like you.','خيار جديد لتجربته. أخبرني إن كان يناسبك.','Une nouvelle possibilité. Dites-moi si elle vous ressemble.')}
function groupScreen(){if(s.members.length){s.members[0].name=s.profile.name||s.members[0].name;s.members[0].interests=[...(s.profile.interests||[])]}if(!s.members.length)s.members=[{name:s.profile.name||tr('Me','أنا','Moi'),interests:[...(s.profile.interests||[])]}];const options=groupOptions();for(const k of Object.keys(s.votes))if(!options.some(p=>p.id===s.votes[k]))delete s.votes[k];return `<main class="group-page"><div class="page-title"><span class="eyebrow muted">${tr('LESS “WHERE?” · MORE “LET’S GO”','حيرة أقل، ولحظات أجمل','MOINS D’HÉSITATION · PLUS DE MOMENTS')}</span><h1>${t('groupTitle')}</h1><p>${tr('Pass the phone. Pick your person. Vote for a little adventure together.','مرّر الهاتف، اختر اسمك، وصوّت لمغامرة تجمعكم.','Passez le téléphone, choisissez votre nom et votez pour votre prochaine sortie.')}</p></div><div class="members">${s.members.map((m,i)=>`<button class="member ${view.groupVoter===i?'active':''}" data-voter="${i}"><span class="avatar">${esc(m.name[0])}</span>${esc(m.name)} ${s.votes[i]?icon('check'):''}</button>`).join('')}<button class="member" data-do="addfriend">${icon('plus')}${t('addFriend')}</button></div><div class="actions"><button class="button soft" data-do="groupdetails">${tr('Time, budget & meeting point','الوقت والميزانية ومكان اللقاء','Horaire, budget et rendez-vous')}</button>${s.groupDetails?`<span class="pill">${esc(s.groupDetails.time||'')} · ${esc(s.groupDetails.budget||'')} AED</span>`:''}</div><p class="small muted">${t('vote')} · ${esc(s.members[view.groupVoter]?.name||'')}</p><div class="group-cards">${options.map(p=>`<button class="vote-card ${s.votes[view.groupVoter]===p.id?'selected':''}" data-vote="${p.id}">${p.img?`<img src="${safeURL(p.img)?esc(p.img):'assets/'+esc(p.img)}" alt="${esc(localPlace(p).name)}" referrerpolicy="no-referrer">`:`<div style="padding:55px 25px" class="small muted">${tr('Photo unavailable from the verified source','الصورة غير متاحة من المصدر الموثق','Photo indisponible auprès de la source vérifiée')}</div>`}<div class="body"><span class="small muted">${esc(localPlace(p).category)}</span><h3>${esc(localPlace(p).name)}</h3><p>${esc(localPlace(p).area)}</p><div class="votes"><span>${Object.values(s.votes).filter(v=>v===p.id).length} ${tr('votes','أصوات','votes')}</span>${icon(s.votes[view.groupVoter]===p.id?'check':'plus')}</div></div></button>`).join('')}</div><div class="group-footer"><p>${tr('Shared-device group demo. Each person enters their own preferences. No invitations or calendar access yet.','نسخة جماعية على جهاز واحد. يُدخل كل شخص تفضيلاته بنفسه. لا توجد دعوات أو مزامنة تقويم بعد.','Démo sur un appareil partagé. Chacun saisit ses préférences. Sans invitations ni accès aux agendas.')}</p><button class="button" data-do="groupplan" ${view.busy?'disabled':''}>${view.busy?tr('Planning…','جارٍ التخطيط…','Planification…'):t('finalize')}${icon('spark')}</button></div></main>`}
function groupOptions(){const entries=ADDY_DATA.places.filter(x=>x.category!=='Business');const scores=entries.map(p=>{let vals=s.members.map(m=>AddyRank.rank(entries,{interests:m.interests},{},'individual').find(x=>x.id===p.id)?.score||0);return {...p,score:(vals.reduce((a,b)=>a+b,0)/Math.max(1,vals.length))*.7+Math.min(...vals)*.3}});return scores.sort((a,b)=>b.score-a.score).slice(0,4)}
const cafeTasks=[['Define the full menu and preparation methods.','Include drinks, hot/cold sandwiches, raw-food handling, seating, takeaway and delivery.','https://www.added.gov.ae/en/set-up/establish-your-business'],['Confirm your economic activity scope.','Do not assume tea and sandwiches always require separate licences. Confirm the activities with ADDED/TAMM.','https://www.added.gov.ae/en/set-up/establish-your-business/licensing-requirements'],['Check the premises before an unconditional lease.','Confirm permitted use, kitchen location, alterations and exhaust feasibility with the relevant authorities and landlord.','https://www.added.gov.ae/en/set-up/establish-your-business'],['Arrange a food-service layout review before fit-out.','ADAFSA guidance links layout to menu and operating model. Food-washing and handwashing facilities are separate; do not assume three kitchens. Guide dated 2019.','https://www.adafsa.gov.ae/CMS/Guidelines/Guideline%20No%20%286%29%20of%202019%20Food%20Service%20Design.pdf'],['Confirm fire-safety approvals and inspections.','A safety compliance certificate is distinct from insurance. Check contractual insurance obligations separately.','https://www.adcda.gov.ae/en/Services'],['Check the actual advertising role before marketing.','Individual creator permits have exemptions; not every owner promoting their own business needs this permit.','https://www.nma.gov.ae/en/initiatives/advertiser-permit-1']];
function defaultPlan(){return (s.type==='business'?(s.profile.sector==='Café & food'?cafeTasks.map((x,i)=>[...(ADDY_COPY[s.lang]?.cafeTasks?.[i]||x.slice(0,2)),x[2]]):[['Define the business activity and legal structure.','Confirm the activity and mainland/free-zone route before committing.','https://www.added.gov.ae/en/set-up/establish-your-business'],['Check premises and activity-specific approvals.','Requirements vary by sector and location.','https://www.added.gov.ae/en/set-up/establish-your-business/licensing-requirements'],['Explore startup support separately from licensing.','Programme admission is not guaranteed.','https://www.hub71.com/latest-news/blog/which-hub71-programme-is-right-for-your-startup']]):[['Confirm your residence route and sponsor.','Choose the relevant route before committing to your move.','https://u.ae/en/information-and-services/visa-and-emirates-id/residence-visas'],['Check family sponsorship, if relevant.','Requirements vary by circumstances. Confirm the official document list.','https://u.ae/en/information-and-services/visa-and-emirates-id/residence-visas/residence-visa-for-family-members'],['Confirm healthcare coverage.','Check networks, exclusions and waiting periods with your insurer.','https://www.doh.gov.ae/en/faq']]).map((x,i)=>({id:'base'+i,title:lx(x[0]),detail:lx(x[1]),url:x[2]}))}
function planScreen(){const list=s.plan.length?s.plan:defaultPlan();return `<main class="plan-page"><div class="page-title"><span class="eyebrow muted">${tr('FROM “MAYBE” TO A NEXT STEP','من فكرة إلى خطوة','DE L’IDÉE À LA PROCHAINE ÉTAPE')}</span><h1>${esc(s.planTitle||t('plan'))}</h1><p>${tr('A plan you can see, change, and make your own.','خطة تراها وتعدّلها لتناسبك.','Un plan concret, à adapter à votre rythme.')}</p></div><div class="checklist">${list.map(x=>`<label class="checkrow ${s.done.includes(x.id)?'done':''}"><input type="checkbox" data-check="${esc(x.id)}" ${s.done.includes(x.id)?'checked':''}><div><h3>${esc(x.title)}</h3><p>${esc(x.detail)}</p>${safeURL(x.url)?`<a href="${esc(x.url)}" target="_blank" rel="noopener">${t('source')}</a>`:''}</div></label>`).join('')}</div><div class="actions"><button class="button" data-do="export">${t('export')}</button><button class="button outline" data-do="print">${tr('Print / PDF','طباعة / PDF','Imprimer / PDF')}</button><button class="textbutton" data-do="ask">${tr('Change it with Addy','عدّلها مع Addy','Modifier avec Addy')}</button></div><div class="notice">${t('actualActions')} ${t('planNotice')} ${tr('Travel times, prices and availability have not been checked live.','لم يتم التحقق المباشر من أوقات السفر والأسعار والتوافر.','Les trajets, prix et disponibilités n’ont pas été vérifiés en direct.')}</div></main>`}
function walkScreen(){return `<main class="walk-page"><div class="page-title"><span class="eyebrow muted">${t('walkthrough')}</span><h1>${tr('A friend. Not another form.','صديق، لا استمارة أخرى.','Un ami. Pas un formulaire.')}</h1><p>${t('walkthroughIntro')}</p></div><div class="walk-cards">${[['mic','walkthrough1',tr('Speak or type. Addy asks what matters next and keeps an editable picture of your preferences.','تحدث أو اكتب. يسأل Addy عما يهمك ويحتفظ بتفضيلات قابلة للتعديل.','Parlez ou écrivez. Addy pose les questions utiles et garde vos préférences modifiables.')],['discover','walkthrough2',tr('Explore one photo card at a time. Save or skip to teach the ranking model what feels right.','استكشف بطاقة مصوّرة في كل مرة. احفظ أو تجاوز لتُعلِّم النموذج ما يناسبك.','Explorez une carte à la fois. Enregistrez ou passez pour affiner les recommandations.')],['group','walkthrough3',tr('Add people on this device, combine preferences, and vote on four possibilities.','أضف الأشخاص على هذا الجهاز، واجمع التفضيلات، وصوّتوا لأحد أربعة خيارات.','Ajoutez vos proches sur cet appareil et votez parmi quatre options.')],['plan','walkthrough4',tr('Turn a choice into a checklist with source links. Export it and mark progress as you go.','حوّل الاختيار إلى قائمة خطوات بمصادرها، وصدّرها وتابع تقدمك.','Transformez votre choix en étapes sourcées, exportez-les et suivez votre progression.')]].map(([i,k,p],n)=>`<article class="walk-card">${icon(i)}<h3>${n+1}. ${t(k)}</h3><p>${p}</p><button class="textbutton" style="margin-top:20px" data-go="${['onboard','discover','together','plan'][n]}">${tr('Try this step','جرّب هذه الخطوة','Essayer cette étape')}</button></article>`).join('')}</div><div class="actions"><button class="button" data-go="welcome">${t('begin')}</button><button class="button outline" data-go="together">${t('together')}</button></div></main>`}
function toast(text){$('.toast')?.remove();const e=document.createElement('div');e.className='toast';e.setAttribute('role','status');e.textContent=text;document.body.append(e);setTimeout(()=>e.remove(),4500)}
function modal(title,content){$('.modal-backdrop')?.remove();const e=document.createElement('div');e.className='modal-backdrop';e.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${esc(title)}</h2><button class="round" id="closemodal" aria-label="Close">${icon('close')}</button></div>${content}</section>`;const priorFocus=document.activeElement;document.body.append(e);const close=()=>{e.remove();if(priorFocus&&document.contains(priorFocus))priorFocus.focus()};$('#closemodal').onclick=close;e.onclick=x=>{if(x.target===e)close()};e.addEventListener('keydown',x=>{if(x.key==='Escape'){close();return}if(x.key==='Tab'){const f=[...e.querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.offsetParent!==null);if(!f.length)return;const first=f[0],last=f[f.length-1];if(x.shiftKey&&document.activeElement===first){x.preventDefault();last.focus()}else if(!x.shiftKey&&document.activeElement===last){x.preventDefault();first.focus()}}});e.querySelector('input,button')?.focus();return e}
function detail(id){const p=catalogue().find(x=>x.id===id);if(!p)return;const e=modal(localPlace(p).name,`${p.img?`<img src="${safeURL(p.img)?esc(p.img):'assets/'+esc(p.img)}" alt="${esc(localPlace(p).name)}" referrerpolicy="no-referrer">`:`<div style="padding:55px 25px" class="small muted">${tr('Photo unavailable from the verified source','الصورة غير متاحة من المصدر الموثق','Photo indisponible auprès de la source vérifiée')}</div>`}<p>${esc(localPlace(p).desc)}</p><div class="fit-note">${reason(p)}</div><p class="small muted" style="margin-top:20px">${t('verified')}: ${esc(p.checked)}. ${t('planNotice')}</p><a href="${esc(p.url)}" target="_blank" rel="noopener">${t('source')}</a><div class="actions"><button class="button" id="planvisit">${tr('Make a plan','أنشئ خطة','Créer un plan')}</button></div>`);$('#planvisit').onclick=()=>{e.remove();if(api.configured){go('ask');sendText('Create a practical step-by-step plan for '+p.name+' using its source '+p.url+'. Respect my budget and preferences. This is a '+p.category+' option; make the steps appropriate, not a generic venue visit.')}else{makePlacePlan(p);go('plan')}}}
function makePlacePlan(p){recordAccountEvent('plan_created',p.id);s.planTitle=localPlace(p).name;s.plan=[{id:'visit1',title:tr('Check opening times and availability','تحقق من المواعيد والتوافر','Vérifier les horaires et disponibilités'),detail:localPlace(p).name,url:p.url},{id:'visit2',title:tr('Confirm the practical details','تأكد من التفاصيل العملية','Confirmer les détails pratiques'),detail:tr('Check tickets, access needs and any dietary requirements directly with the venue.','تحقق من التذاكر ومتطلبات سهولة الوصول والمتطلبات الغذائية مباشرة مع المكان.','Confirmez billets, accessibilité et besoins alimentaires auprès du lieu.'),url:p.url},{id:'visit3',title:tr('Choose a time and plan your journey','اختر الوقت وخطط للطريق','Choisir une heure et préparer le trajet'),detail:tr('Check a live maps service before leaving. No live traffic estimate is available here.','تحقق من خدمة خرائط مباشرة قبل المغادرة. لا يتوفر تقدير مباشر للمرور هنا.','Consultez une carte en direct avant le départ. Pas d’estimation du trafic ici.'),url:'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(p.name+' Abu Dhabi')}];s.done=[];save()}
function groupDetails(){const d=s.groupDetails||{},e=modal(tr('Make it work for everyone','خطة تناسب الجميع','Un plan pour tout le monde'),`<form id="groupdetailsform"><label class="field">${tr('When would you like to meet?','متى تودون اللقاء؟','Quand souhaitez-vous vous retrouver ?')}<input id="gtime" type="datetime-local" value="${esc(d.time||'')}"></label><label class="field">${tr('Budget per person, AED','الميزانية للشخص، درهم','Budget par personne, AED')}<input id="gbudget" type="number" min="0" max="10000" value="${esc(d.budget||'')}"></label><label class="field">${tr('Meeting area','منطقة اللقاء','Quartier de rendez-vous')}<input id="garea" maxlength="100" value="${esc(d.area||'')}"></label><label class="field">${tr('Transport preference','وسيلة النقل المفضلة','Transport souhaité')}<select id="gtransport"><option value="Taxi / ride-hailing">${esc(lx("Taxi / ride-hailing"))}</option><option value="Own car">${esc(lx("Own car"))}</option><option value="Public transport">${esc(lx("Public transport"))}</option><option value="Walking nearby">${esc(lx("Walking nearby"))}</option></select></label><p class="small muted">${tr('These are your requested constraints, not verified availability or prices. Relevant group preferences are sent to OpenAI when you create the plan.','هذه تفضيلاتكم المطلوبة وليست أسعارًا أو توافرًا مؤكدًا. تُرسل التفضيلات ذات الصلة إلى OpenAI عند إنشاء الخطة.','Ce sont vos contraintes, pas des prix ou disponibilités vérifiés. Les préférences utiles sont envoyées à OpenAI pour créer le plan.')}</p><button class="button">${t('save')}</button></form>`);if(d.transport)$('#gtransport').value=d.transport;$('#groupdetailsform').onsubmit=x=>{x.preventDefault();s.groupDetails={time:$('#gtime').value,budget:$('#gbudget').value,area:$('#garea').value.trim(),transport:$('#gtransport').value,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};save();e.remove();render()}}
function addFriend(){const e=modal(t('addFriend'),`<p class="small muted">${tr('Ask your friend to enter their own name and interests.','اطلب من صديقك إدخال اسمه واهتماماته بنفسه.','Demandez à votre proche de saisir son nom et ses intérêts.')}</p><form id="friendform"><label class="field">${t('name')}<input id="friendname" maxlength="40" required></label><label class="field">${t('interests')}<select id="friendinterest"><option value="Food & dining">${esc(lx("Food & dining"))}</option><option value="Art & culture">${esc(lx("Art & culture"))}</option><option value="Nature & outdoors">${esc(lx("Nature & outdoors"))}</option><option value="Architecture">${esc(lx("Architecture"))}</option><option value="Technology & AI">${esc(lx("Technology & AI"))}</option></select></label><button class="button">${t('addFriend')}</button></form>`);$('#friendform').onsubmit=x=>{x.preventDefault();if(s.members.length>=8){toast(lx('Maximum 8 people in this demo.'));return}const name=$('#friendname').value.trim();if(!name)return;s.members.push({name,interests:[$('#friendinterest').value]});s.votes={};view.groupVoter=s.members.length-1;save();e.remove();render()}}
function profileLabel(k){const m={moveStatus:['Moving status','حالة الانتقال','Situation'],setupStage:['Setup stage','مرحلة التأسيس','Étape du projet'],ageRange:['Age','العمر','Âge'],gender:['Gender','الجنس','Genre'],origin:['Coming from','قادم من','Origine'],name:['Name','الاسم','Nom'],interests:['Interests','الاهتمامات','Centres d’intérêt'],priorities:['Priorities','الأولويات','Priorités'],dislikes:['Prefer to avoid','ما تفضل تجنبه','À éviter'],family:['Household','الأسرة','Foyer'],sector:['Business sector','قطاع الأعمال','Secteur'],timeline:['Moving timeline','موعد الانتقال','Calendrier'],budget:['Planning budget','ميزانية التخطيط','Budget'],goals:['Goals','الأهداف','Objectifs'],cuisine:['Food preferences','تفضيلات الطعام','Cuisine'],pace:['Your pace','إيقاعك المفضل','Votre rythme'],area:['Preferred area','المنطقة المفضلة','Quartier'],businessConcept:['Business concept','فكرة المشروع','Projet'],setupRoute:['Setup route','مسار التأسيس','Mode d’implantation']};return m[k]?tr(...m[k]):k}
function profile(){const e=modal(t('profile'),`<form id="profileform"><label class="field">${t('name')}<input id="profilename" maxlength="60" value="${esc(s.profile.name||'')}"></label><label class="field">${t('interests')}<input id="profileinterests" value="${esc((s.profile.interests||[]).map(lx).join(', '))}"></label><label class="field">${profileLabel('dislikes')}<input id="profiledislikes" value="${esc((s.profile.dislikes||[]).join(', '))}"></label><details style="margin:20px 0"><summary>${tr('More preferences','المزيد من التفضيلات','Autres préférences')}</summary>${['ageRange','gender','origin','moveStatus','setupStage','family','sector','timeline','budget','goals','cuisine','pace','area','businessConcept','setupRoute'].map(k=>`<label class="field">${esc(profileLabel(k))}<input data-profile-field="${k}" value="${esc(lx(s.profile[k]||''))}" maxlength="100"></label>`).join('')}</details><button class="button">${t('save')}</button></form><div class="actions"><button class="button soft" id="restartonboard">${tr('Restart onboarding','أعد التعارف','Reprendre le parcours')}</button><button class="textbutton" id="resetprofile">${t('reset')}</button></div><p class="small muted">${tr('Preferences and votes are stored on this device. The model learns from explicit saves and dislikes; undoing feedback resets that signal.','تُحفظ التفضيلات والأصوات على هذا الجهاز. يتعلم النموذج من الحفظ وعدم الإعجاب الصريح.','Préférences et votes restent sur cet appareil. Le modèle apprend des enregistrements et refus explicites.')}</p>`);$('#profileform').onsubmit=x=>{x.preventDefault();document.querySelectorAll('[data-profile-field]').forEach(i=>{s.profile[i.dataset.profileField]=unlx(i.value.trim())});s.profile.name=$('#profilename').value.trim();s.profile.nameConfirmed=!!s.profile.name;s.profile.dislikes=($('#profiledislikes')?.value||'').split(',').map(x=>x.trim()).filter(Boolean);s.profile.interests=$('#profileinterests').value.split(',').map(x=>unlx(x.trim())).filter(Boolean).slice(0,10);save();e.remove();render()};$('#restartonboard').onclick=()=>{if(confirm(tr('Start onboarding again? This replaces your current profile.','هل تريد إعادة التعارف؟ سيستبدل هذا ملفك الحالي.','Recommencer le parcours ? Votre profil actuel sera remplacé.'))){view.requestController?.abort();view.requestGeneration=(view.requestGeneration||0)+1;view.busy=false;stopVoice();e.remove();s.profile={};s.onboardingAnswers=0;s.intakeStep=0;turns=[];conversationHistory.onboarding=[];s.onboardingCompleted=false;view.reply='';save();go('onboard')}};$('#resetprofile').onclick=()=>{if(confirm(t('reset')+'?')){stopVoice();localStorage.removeItem('addy-v2');location.reload()}}}
async function sendText(text,forcedMode,requestOptions={}){if((forcedMode==='onboarding'||(!forcedMode&&s.screen==='onboard'))&&intakeStep()<4)return;if((forcedMode==='onboarding'||(!forcedMode&&s.screen==='onboard'))&&intakeStep()>=6){go('review');return}if(!text||view.busy)return;view.lastRequestOk=false;if(/(?:i(?: am|'m|’m) broke|low budget|on a budget|cheap|affordable|no money|don.t have (?:any )?money|can.t afford|ميزانية محدودة|رخيص|pas d.argent|petit budget)/i.test(text)&&!/not broke|not on a budget/i.test(text)){s.profile.budget='Low-cost options requested';s.preferredIds=[];save()}view.transcript=text;view.reply='';view.resultCards=[];const q=currentQuestion();if(!api.configured&&s.screen==='onboard'){view.reply=tr('AI is not connected yet. Add your preferences with the edit button, or try again shortly.','الذكاء الاصطناعي غير متصل بعد. أضف تفضيلاتك عبر التعديل أو حاول بعد قليل.','L’IA n’est pas encore connectée. Modifiez vos préférences ou réessayez.');render();return}if(!api.configured){if(s.screen==='onboard'&&q){if(q.key==='name')s.profile.nameConfirmed=true;if(q.key==='interests'){const m=[];if(/art|culture|museum|فن|ثقاف/i.test(text))m.push('Art & culture');if(/food|coffee|café|eat|قهو|طعام/i.test(text))m.push('Food & dining');if(/nature|outdoor|beach|طبيع|بحر/i.test(text))m.push('Nature & outdoors');if(/tech|ai|تقني/i.test(text))m.push('Technology & AI');s.profile.interests=m.length?m:[text.slice(0,80)]}else s.profile[q.key]=text.slice(0,100);save();render();return}view.reply=tr('I’m in curated mode for now. You can explore real places, make a group plan, or use the sourced checklist. Live conversation is awaiting API setup.','أنا في وضع المحتوى المختار حاليًا. يمكنك استكشاف الأماكن والتخطيط مع المجموعة. المحادثة المباشرة تنتظر إعداد API.','Le mode sélection est actif. Explorez les lieux, planifiez en groupe ou consultez la checklist. La conversation IA attend la configuration API.');render();return}
const requestId=(view.requestGeneration||0)+1;view.requestGeneration=requestId;const controller=new AbortController();view.requestController=controller;view.requestVoice=requestOptions.voiceSession||null;const conversationMode=forcedMode||(s.screen==='onboard'?'onboarding':'concierge');const activeHistory=conversationHistory[conversationMode];const profileBeforeRequest=JSON.stringify(s.profile);view.busy=true;view.voice='thinking';render();try{const res=await fetch('/api/concierge',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,mode:forcedMode||(s.screen==='onboard'?'onboarding':'concierge'),language:s.lang,type:s.type,profile:s.profile,plan:s.plan,planTitle:s.planTitle,history:activeHistory.slice(-6),shortlist:ranked().slice(0,6).map(p=>({id:p.id,name:p.name,tags:p.tags,url:p.url,description:p.desc})),intakeVersion:conversationMode==='onboarding'?2:undefined,onboardingTurn:Math.max(1,intakeStep()-3),question:q?.key||null})});const data=await res.json();if(controller.signal.aborted||requestId!==view.requestGeneration||(requestOptions.voiceSession&&(voiceSession!==requestOptions.voiceSession||requestOptions.voiceSession.turn!==requestOptions.turn)))return;if(!res.ok)throw new Error(data.error||'Request failed');view.reply=data.reply||'';if(Array.isArray(data.discoveries)){s.discoveries=[...new Map([...data.discoveries.filter(x=>x&&typeof x.name==='string'&&safeURL(x.url)),...(s.discoveries||[])].map(x=>[x.url,x])).values()].slice(0,20);if(s.discoveries.length)s.preferredIds=s.discoveries.map(x=>x.id)}view.sources=Array.isArray(data.sources)?data.sources.filter(x=>safeURL(x.url)).slice(0,5):[];if(data.profile&&JSON.stringify(s.profile)===profileBeforeRequest)applyPreferences(data.profile);view.lastRequestOk=true;if(conversationMode==='onboarding'){s.onboardingAnswers=Math.min(2,(s.onboardingAnswers||0)+1);s.intakeStep=Math.min(6,intakeStep()+1);view.reply=onboardingPrompt()}if(Array.isArray(data.plan)&&data.plan.length){s.plan=data.plan.filter(x=>x&&typeof x.title==='string').slice(0,10).map((x,i)=>({id:'plan'+i,title:x.title.slice(0,180),detail:String(x.detail||'').slice(0,700),url:safeURL(x.url)?x.url:''}));s.planTitle=String(data.planTitle||t('plan')).slice(0,180);s.done=[];recordAccountEvent('plan_created')}if(Array.isArray(data.itemIds)&&data.itemIds.length){s.preferredIds=[...(s.discoveries||[]).map(x=>x.id),...data.itemIds]}view.resultCards=catalogue().filter(p=>(data.discoveries||[]).some(x=>x.id===p.id)||(data.itemIds||[]).includes(p.id)).slice(0,2);activeHistory.push({role:'user',content:text},{role:'assistant',content:view.reply});save()}catch(e){if(e.name==='AbortError'||requestId!==view.requestGeneration)return;view.reply=tr('I couldn’t complete that request. Your profile is safe; please try again.','لم أتمكن من إكمال الطلب. تفضيلاتك محفوظة، حاول مجددًا.','La demande n’a pas abouti. Vos préférences sont conservées, réessayez.');toast(String(e.message).slice(0,150))}finally{if(requestId===view.requestGeneration){view.busy=false;view.requestVoice=null;view.voice='idle';render()}}}
function downloadPlan(){const rows=s.plan.length?s.plan:defaultPlan(),a=document.createElement('a');const text=`Addy — ${esc(s.planTitle||t('plan'))}\n\n`+rows.map(x=>`${s.done.includes(x.id)?'[x]':'[ ]'} ${x.title}\n${x.detail}\n${x.url||''}`).join('\n\n')+'\n\n'+t('actualActions')+' '+t('planNotice');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='addy-plan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
let journeyActive=false;
function splash(next){if(journeyActive)return;journeyActive=true;const e=document.createElement('div');e.className='splash heritage-journey';e.setAttribute('role','dialog');e.setAttribute('aria-label',tr('Your journey to Abu Dhabi','رحلتك إلى أبوظبي','Votre voyage vers Abu Dhabi'));e.innerHTML=`<div class="heritage-scene" aria-hidden="true"></div><div class="journey-caption"><div class="brand">addy<i>.</i></div><p>${tr('From a new beginning. To belonging.','من بداية جديدة، إلى شعور بالانتماء.','Un nouveau départ. Un sentiment d’appartenance.')}</p><div class="journey-line" aria-hidden="true"><i></i></div></div><button class="textbutton journey-skip">${tr('Skip animation','تخطي الحركة','Passer l’animation')}</button>`;document.body.append(e);let ended=false;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;let timer;function cleanup(){if(ended)return false;ended=true;clearTimeout(timer);document.removeEventListener('keydown',key);e.remove();journeyActive=false;cancelJourney=()=>{};return true}cancelJourney=cleanup;function end(){if(!cleanup())return;next();document.querySelector('main h1,main h2')?.setAttribute('tabindex','-1');document.querySelector('main h1,main h2')?.focus({preventScroll:true})}function key(ev){if(ev.key==='Escape'){ev.preventDefault();end()}if(ev.key==='Tab'){ev.preventDefault();e.querySelector('button').focus()}}document.addEventListener('keydown',key);e.querySelector('button').onclick=end;e.querySelector('button').focus({preventScroll:true});requestAnimationFrame(()=>requestAnimationFrame(()=>e.classList.add('travelling')));timer=setTimeout(end,reduce?250:3800)}

function bind(){const intake=$('#intakeform');if(intake)intake.onsubmit=submitIntake;document.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{go('ask');sendText('Find current '+b.dataset.service+' options in Abu Dhabi relevant to my stated preferences. Use official provider sources. Give useful contact or service details only if verified; do not infer health conditions or guarantee availability.')});const hold=$('[data-hold]');if(hold){hold.addEventListener('contextmenu',e=>e.preventDefault());hold.onclick=e=>{e.preventDefault();if(voiceSession?.rt.holding)endHold();else beginHold()};}$('#confirmname')?.addEventListener('click',()=>confirmName($('#heardname').value));$('#skipname')?.addEventListener('click',()=>{view.pendingName='';render()});$('#language')?.addEventListener('change',e=>{s.lang=e.target.value;view.reply='';save();render()});document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{view.reply='';go(b.dataset.go)});document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>{s.type=b.dataset.start;s.slide=0;splash(()=>go(s.onboardingCompleted?'discover':s.profile.name?'onboard':'story'))});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>sendText(b.dataset.answer));$('#voiceform')?.addEventListener('submit',async e=>{e.preventDefault();const value=$('#voiceinput').value.trim();if(!value)return;const v=voiceSession,turn=v?.turn,review=view.reviewPending&&v?.kind==='recorded';view.reviewPending=false;await sendText(value,undefined,review?{voiceSession:v,turn}:{});if(review&&voiceSession===v&&view.lastRequestOk)await speakRecordedReply(view.reply,v,turn)});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{view.filter=b.dataset.filter;view.focusCardId=null;s.deck=0;render()});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));document.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>{view.lastFeedback={id:b.dataset.id,previous:s.feedback[b.dataset.id]};s.feedbackHistory=[...(s.feedbackHistory||[]),view.lastFeedback].slice(-20);view.focusCardId=null;s.feedback[b.dataset.id]=+b.dataset.feedback;recordAccountEvent(+b.dataset.feedback>0?'venue_saved':'venue_skipped',b.dataset.id);save();s.deck=0;render();toast(+b.dataset.feedback>0?tr('Saved. I’ll learn from that.','تم الحفظ. سأتعلم من اختيارك.','Enregistré. J’en tiens compte.'):tr('Noted. Let’s find a better fit.','حسنًا، لنجد خيارًا أنسب.','Noté. Trouvons mieux.'))});document.querySelectorAll('[data-voter]').forEach(b=>b.onclick=()=>{view.groupVoter=+b.dataset.voter;render()});document.querySelectorAll('[data-vote]').forEach(b=>b.onclick=()=>{s.votes[view.groupVoter]=b.dataset.vote;save();render()});document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{if(b.checked)recordAccountEvent('plan_step_completed',b.dataset.check);s.done=b.checked?[...new Set([...s.done,b.dataset.check])]:s.done.filter(x=>x!==b.dataset.check);save();render()});document.querySelectorAll('[data-do]').forEach(b=>b.onclick=async()=>{const a=b.dataset.do;if(a==='nextstory'){if(s.slide<ADDY_DATA.leaders.length-1){s.slide++;render()}else go('onboard')}if(a==='finish'){stopVoice();go('review')}if(a==='approveprofile'){if(view.busy)return;if($('#accountconsent')?.checked){b.disabled=true;const ok=await saveAccountSummary();b.disabled=false;if(!ok)return}else{s.ownerSummaryConsent=false} s.onboardingCompleted=true;save();view.reply='';stopVoice();go('discover');await sendText('Find current Abu Dhabi places and practical relocation services matching my stated interests, household and priorities. Recommend up to four highly relevant options with official sources and useful details. Include hotels, healthcare directories, movers, typing centers or government services only when relevant. Do not infer medical needs or claim completeness.','concierge')}if(a==='ask'){view.reply='';go('ask')}if(a==='focusinput')$('#voiceinput')?.focus();if(a==='voice')startVoice();if(a==='stopvoice'){stopVoice();render()}if(a==='enableaudio'&&voiceSession?.player){voiceSession.player.play().then(()=>{view.audioBlocked=false;render()}).catch(()=>toast(tr('Audio is still blocked by the browser.','ما زال المتصفح يحظر الصوت.','Le navigateur bloque encore le son.')))}if(a==='undofeedback'){const f=(s.feedbackHistory||[]).pop()||view.lastFeedback;if(f){if(f.previous===undefined)delete s.feedback[f.id];else s.feedback[f.id]=f.previous;view.focusCardId=f.id;view.filter='All';view.lastFeedback=null;s.deck=0;save();render();toast(tr('Card restored.','تمت استعادة البطاقة.','Carte rétablie.'))}}if(a==='nextcard'){s.deck++;render()}if(a==='clearfeedback'){s.feedback={};save();render()}if(a==='profile')profile();if(a==='basics')basicProfile();if(a==='intakeprofile'){const panel=modal(t('profile'),(document.querySelector('.profile-unfolding')?.outerHTML||'')+`<button class="button" id="editintakeprofile">${t('edit')}</button>`);$('#editintakeprofile').onclick=()=>{panel.remove();profile()};}if(a==='intakeback'){view.requestController?.abort();view.requestGeneration=(view.requestGeneration||0)+1;view.busy=false;stopVoice();view.reply='';view.transcript='';if(intakeStep()>0){s.intakeStep=intakeStep()-1;save();render()}else go('welcome')}if(a==='restart'){if(confirm(tr('Start onboarding again? This replaces your current profile.','إعادة التعارف واستبدال الملف الحالي؟','Recommencer et remplacer votre profil ?'))){view.requestController?.abort();view.requestGeneration=(view.requestGeneration||0)+1;view.busy=false;stopVoice();s.profile={};s.onboardingAnswers=0;s.intakeStep=0;turns=[];conversationHistory.onboarding=[];s.onboardingCompleted=false;view.reply='';save();go('onboard')}}if(a==='newchat'){turns=[];conversationHistory.concierge=[];view.reply='';view.transcript='';view.resultCards=[];render()}if(a==='addfriend')addFriend();if(a==='groupdetails')groupDetails();if(a==='export')downloadPlan();if(a==='print')window.print();if(a==='groupplan'){if(view.busy)return;const opts=groupOptions();if(!Object.keys(s.votes).length){toast(t('vote'));return}const p=[...opts].sort((a,b)=>Object.values(s.votes).filter(x=>x===b.id).length-Object.values(s.votes).filter(x=>x===a.id).length)[0];makePlacePlan(p);if(s.groupDetails){s.plan.unshift({id:'group-constraints',title:tr('Your group’s requested plan','خطة مجموعتكم المطلوبة','Vos contraintes de groupe'),detail:tr('Time: ','الوقت: ','Horaire : ')+(s.groupDetails.time||'—')+' · '+tr('Budget per person: ','ميزانية الشخص: ','Budget par personne : ')+(s.groupDetails.budget||'—')+' AED · '+(s.groupDetails.area||'')+' · '+(s.groupDetails.transport||''),url:''})}s.planTitle=tr('Our plan: ','خطتنا: ','Notre sortie : ')+localPlace(p).name;save();if(api.configured){b.disabled=true;b.textContent=tr('Planning…','جارٍ التخطيط…','Planification…');await sendText('Create a practical group visit plan for the group-selected venue '+p.name+'. Do not change the voted choice. There are '+s.members.length+' participants. Shared interests: '+JSON.stringify(s.members.map(m=>m.interests))+'. User-specified planning constraints: '+JSON.stringify(s.groupDetails||{})+'. Verify budget fit only if supported by sources; otherwise identify what to confirm. Include time sequence, transport check and official booking link. Do not claim anything booked.')}go('plan')}});const card=$('#placecard');if(card){let x=0;card.addEventListener('touchstart',e=>x=e.changedTouches[0].clientX,{passive:true});card.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-x;if(Math.abs(d)>85)card.querySelector(`[data-feedback="${d>0?2:-1}"]`)?.click()},{passive:true})}}
function paintVoiceText(){const transcript=$('[data-live-transcript]');if(transcript){transcript.textContent=view.transcript||'';transcript.hidden=!view.transcript;const details=transcript.closest('details');if(details)details.hidden=!view.transcript}const title=(s.screen==='onboard'?null:$('.cinema-question h1'))||$('.assistant-answer h2')||$('.voice-body h2');if(title){title.textContent=view.reply||(s.screen==='onboard'?onboardingPrompt():tr('I’m listening.','أنا أستمع.','Je vous écoute.'));title.classList.add('answer')}const status=$('.voice-dock>p');if(status)status.textContent=voiceSession?.mode==='ptt'&&view.voice==='idle'?tr('Tap to record · tap again to finish','اضغط للتسجيل ثم اضغط للإنهاء','Touchez pour enregistrer, puis pour terminer'):t(view.voice)}
function progressScore(){return Math.min(80,new Set(s.profile.interests||[]).size*10+['goals','pace','timeline','area','cuisine','priorities','dislikes','businessConcept','sector'].filter(k=>Array.isArray(s.profile[k])?s.profile[k].length:!!s.profile[k]).length*10)}
function applyPreferences(input){if(!input||typeof input!=='object')return;const before=progressScore();for(const k of ['name','family','sector','timeline','budget','goals','cuisine','pace','area','businessConcept','setupRoute','setupStage','moveStatus','origin']){if(typeof input[k]!=='string'||!input[k].trim())continue;if(k==='budget'&&AddyRank.lowBudget(s.profile))continue;if(k==='name'){const name=input[k].trim().slice(0,100);if(name!==s.profile.name||!s.profile.nameConfirmed)view.pendingName=name;continue}s.profile[k]=input[k].slice(0,100)}for(const k of ['interests','dislikes','priorities'])if(Array.isArray(input[k])&&input[k].length)s.profile[k]=input[k].filter(x=>typeof x==='string').slice(0,12);save();if(progressScore()>before)toast(tr('A clearer picture. +','صورة أوضح. +','Une vision plus claire. +')+(progressScore()-before)+tr(' exploration points.',' نقاط استكشاف تجريبية.',' points découverte de démo.'))}
function confirmName(name){const n=String(name||'').trim().slice(0,100);if(!n)return;s.profile.name=n;s.profile.nameConfirmed=true;view.pendingName='';save();render()}
async function startVoice(){if(view.connecting||voiceSession)return;if(typeof MediaRecorder==='undefined'){toast(tr('Voice recording is not supported here. Please type.','التسجيل الصوتي غير مدعوم هنا. يرجى الكتابة.','L’enregistrement vocal est indisponible. Écrivez votre message.'));return}if(!api.configured){toast(tr('Voice needs the API connection.','الصوت يحتاج إلى اتصال API.','La voix nécessite la connexion API.'));return}if(view.voiceConsentGranted){connectVoice(true);return}const e=modal(t('talk'),`<p>${tr('Tap once to record, then tap again to finish. Addy transcribes your recording and gives one reply. Recording is never automatic.','اضغط مرة للتسجيل ثم مرة أخرى للإنهاء. يحوّل Addy التسجيل إلى نص، ويحدّث ملفك، ثم يقدم ردًا صوتيًا واحدًا بالذكاء الاصطناعي.','Touchez une fois pour enregistrer, puis une autre fois pour terminer. Addy transcrit, met à jour votre profil et donne une seule réponse vocale IA.')}</p><p class="small muted">${t('voicePrivacy')} ${tr('No autonomous listening. Quiet recordings are rejected when the audio-level check is available.','لا يوجد استماع تلقائي. تُرفض التسجيلات الصامتة عندما يتوفر فحص مستوى الصوت.','Aucune écoute autonome. Les enregistrements silencieux sont rejetés lorsque le contrôle du niveau audio est disponible.')}</p><button class="button" id="voiceconsent">${t('consent')}</button>`);$('#voiceconsent').onclick=()=>{view.voiceConsentGranted=true;e.remove();connectVoice(true)}}
async function connectVoice(recordImmediately=false){if(view.connecting)return;view.connecting=true;const generation=++voiceGeneration;let stream,ctx;view.voice='thinking';render();try{const AC=window.AudioContext||window.webkitAudioContext;ctx=AC?new AC():null;if(ctx)await ctx.resume();stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:false,channelCount:1}});if(generation!==voiceGeneration||!['onboard','ask'].includes(s.screen)){stream.getTracks().forEach(t=>t.stop());ctx?.close();return}stream.getAudioTracks().forEach(t=>t.enabled=false);let analyser=null;if(ctx){const source=ctx.createMediaStreamSource(stream);analyser=ctx.createAnalyser();analyser.fftSize=512;source.connect(analyser)}const player=document.createElement('audio');player.autoplay=true;player.hidden=true;document.body.append(player);const v={kind:'recorded',mode:'ptt',stream,ctx,analyser,player,turn:0,rt:{holding:false,tools:false,awaitingTranscript:false},audioURL:null};voiceSession=v;view.connecting=false;view.voice='idle';v.timer=setTimeout(()=>{if(voiceSession===v){stopVoice();render()}},5*60*1000);player.onended=()=>{if(voiceSession===v){view.voice='idle';v.rt.tools=false;render()}};const welcome=s.screen==='onboard'?tr('Hi, I’m Addy. Tell me what matters to you, and I’ll personalize your Abu Dhabi.','مرحبًا، أنا Addy. أخبرني بما يهمك لأساعدك على اكتشاف أبوظبي بطريقتك.','Bonjour, je suis Addy. Dites-moi ce qui compte pour vous, et personnalisons votre Abu Dhabi.'):tr('Hi, I’m Addy. What would you like to make happen today?','مرحبًا، أنا Addy. ماذا تود أن ننجز اليوم؟','Bonjour, je suis Addy. Que souhaitez-vous faire aujourd’hui ?');view.reply='';render();if(recordImmediately)beginHold();else speakRecordedReply(welcome,v,0)}catch(e){stream?.getTracks().forEach(t=>t.stop());ctx?.close();if(generation!==voiceGeneration)return;view.connecting=false;view.voice='idle';render();toast(tr('Microphone access is unavailable. You can type instead.','الميكروفون غير متاح. يمكنك الكتابة بدلًا من ذلك.','Microphone indisponible. Vous pouvez écrire.'))}}
function beginHold(e){if(s.screen==='onboard'&&(intakeStep()<4||intakeStep()>=6))return;if(typeof MediaRecorder==='undefined'){toast(tr('Recording is unavailable. Please type.','التسجيل غير متاح. يرجى الكتابة.','Enregistrement indisponible. Écrivez.'));return}const v=voiceSession;if(!v||v.kind!=='recorded'||view.busy||v.rt.holding||v.rt.tools||v.rt.awaitingTranscript)return;e?.preventDefault();v.turn++;v.audioAbort?.abort();v.player.pause();v.player.currentTime=0;view.reviewPending=false;v.rt.holding=true;v.started=performance.now();v.voicedMs=0;v.peak=0;v.chunks=[];view.audioBlocked=false;view.voice='listening';v.stream.getAudioTracks().forEach(t=>t.enabled=true);if(v.ctx?.state==='suspended')v.ctx.resume().catch(()=>{});const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(x=>MediaRecorder.isTypeSupported(x));try{v.recorder=new MediaRecorder(v.stream,mime?{mimeType:mime}:undefined)}catch{v.rt.holding=false;v.stream.getAudioTracks().forEach(t=>t.enabled=false);view.voice='idle';render();toast(tr('Recording is unavailable in this browser. Please type.','التسجيل غير متاح في هذا المتصفح. يرجى الكتابة.','L’enregistrement est indisponible. Écrivez votre message.'));return}const turn=v.turn;v.recorder.ondataavailable=x=>{if(x.data.size)v.chunks.push(x.data)};v.recorder.onstop=()=>processRecordedTurn(v,turn,new Blob(v.chunks,{type:v.recorder.mimeType||'audio/webm'}),performance.now()-v.started,v.voicedMs,v.peak);try{v.recorder.start()}catch{v.rt.holding=false;v.stream.getAudioTracks().forEach(t=>t.enabled=false);view.voice='idle';render();toast(tr('Recording could not start. Please type.','تعذر بدء التسجيل. يرجى الكتابة.','Impossible de démarrer l’enregistrement. Écrivez.'));return}const samples=v.analyser?new Uint8Array(v.analyser.fftSize):null;let last=performance.now();function measure(now){if(voiceSession!==v||!v.rt.holding)return;if(samples){v.analyser.getByteTimeDomainData(samples);let sum=0;for(const x of samples)sum+=((x-128)/128)**2;const rms=Math.sqrt(sum/samples.length);v.peak=Math.max(v.peak,rms);if(rms>.012)v.voicedMs+=Math.min(50,now-last)}last=now;v.levelFrame=requestAnimationFrame(measure)}v.levelFrame=requestAnimationFrame(measure);v.recordTimer=setTimeout(endHold,s.screen==='onboard'?30000:60000);const b=$('[data-hold]');b?.classList.add('on');if(b)b.setAttribute('aria-pressed','true');if(e?.pointerId!=null)b?.setPointerCapture(e.pointerId);paintVoiceText();const status=$('.voice-dock>p');if(status)status.textContent=tr('Recording · tap the microphone to finish','جارٍ التسجيل · اضغط الميكروفون للإنهاء','Enregistrement · touchez le micro pour terminer')}
function endHold(){const v=voiceSession;if(!v||v.kind!=='recorded'||!v.rt.holding)return;v.rt.holding=false;v.rt.awaitingTranscript=true;cancelAnimationFrame(v.levelFrame);clearTimeout(v.recordTimer);v.stream.getAudioTracks().forEach(t=>t.enabled=false);$('[data-hold]')?.classList.remove('on');$('[data-hold]')?.setAttribute('aria-pressed','false');if(v.recorder?.state==='recording')v.recorder.stop();view.voice='thinking';paintVoiceText();const status=$('.voice-dock>p');if(status)status.textContent=tr('Transcribing your words…','جارٍ تحويل كلامك إلى نص…','Transcription de vos paroles…');const b=$('[data-hold]');if(b)b.disabled=true}
async function readTranscript(response,v,turn){if(!response.headers?.get('content-type')?.includes('text/event-stream'))return response.json();const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',draft='',final='',done=false,logs=[];while(true){const part=await reader.read();if(voiceSession!==v||turn!==v.turn){await reader.cancel();throw new DOMException('Cancelled','AbortError')}if(part.done)break;buffer+=decoder.decode(part.value,{stream:true});const events=buffer.split(/\r?\n\r?\n/);buffer=events.pop();for(const event of events){const line=event.split(/\r?\n/).filter(x=>x.startsWith('data:')).map(x=>x.slice(5).trim()).join('\n');if(!line||line==='[DONE]')continue;let d;try{d=JSON.parse(line)}catch{continue}if(d.type==='error')throw new Error('Transcription unavailable');if(d.type==='transcript.text.delta'){draft+=d.delta||'';view.transcript=draft;paintVoiceText()}if(d.type==='transcript.text.done'){final=d.text||draft;done=true;if(Array.isArray(d.logprobs))logs=d.logprobs}}}if(!done)throw new Error('Incomplete transcript');const valid=logs.filter(x=>typeof x.logprob==='number');return{text:final,reviewSuggested:valid.length>0&&valid.reduce((a,x)=>a+x.logprob,0)/valid.length<-.9}}
async function processRecordedTurn(v,turn,blob,duration,voicedMs,peak){if(voiceSession!==v||turn!==v.turn)return;if(duration<250||blob.size<400||(v.analyser&&(voicedMs<160||peak<.018))){v.rt.awaitingTranscript=false;view.voice='idle';render();toast(tr('I didn’t hear enough speech. Hold while speaking, or type it.','لم ألتقط كلامًا كافيًا. اضغط أثناء التحدث أو اكتب رسالتك.','Je n’ai pas entendu assez de parole. Maintenez en parlant, ou écrivez.'));return}try{v.requestAbort=new AbortController();const form=new FormData();form.append('stream','true');form.append('file',blob,blob.type.includes('mp4')?'turn.mp4':'turn.webm');const r=await fetch('/api/transcribe',{method:'POST',body:form,signal:v.requestAbort.signal});const d=await readTranscript(r,v,turn);if(voiceSession!==v||turn!==v.turn)return;if(!r.ok)throw new Error(d.error||'Transcription failed');const text=String(d.text||'').trim();if(!text||/^\[?(silence|noise|music|inaudible)\]?$/i.test(text))throw new Error('No clear speech');view.transcript=text;v.rt.awaitingTranscript=false;if(d.reviewSuggested||!v.analyser){view.reviewPending=true;view.reply=tr('Please check what I heard, edit it if needed, and press Send.','راجع ما التقطته وعدّله إن لزم ثم اضغط إرسال.','Vérifiez ce que j’ai entendu, corrigez si besoin, puis envoyez.');view.voice='idle';render();const input=$('#voiceinput');if(input){input.value=text;input.focus()}return}v.rt.tools=true;await sendText(text,s.screen==='onboard'?'onboarding':'concierge',{voiceSession:v,turn});if(voiceSession!==v||turn!==v.turn)return;v.rt.tools=false;view.voice='idle';render();if(view.lastRequestOk)await speakRecordedReply(view.reply,v,turn);else{view.voice='idle';render()}}catch(e){if(voiceSession!==v)return;v.rt.awaitingTranscript=false;v.rt.tools=false;view.voice='idle';render();if(e.name!=='AbortError')toast(tr('That recording wasn’t clear enough to use. Please try again or type.','لم يكن التسجيل واضحًا بما يكفي. حاول مجددًا أو اكتب.','Cet enregistrement n’était pas assez clair. Réessayez ou écrivez.'))}}
async function speakRecordedReply(text,v,turn){if(voiceSession!==v||v.turn!==turn)return;try{v.audioAbort=new AbortController();const r=await fetch('/api/speech',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,language:s.lang}),signal:v.audioAbort.signal});if(!r.ok)throw new Error('Speech unavailable');const blob=await r.blob();if(voiceSession!==v||v.turn!==turn||v.rt.holding)return;if(v.audioURL)URL.revokeObjectURL(v.audioURL);v.audioURL=URL.createObjectURL(blob);v.player.src=v.audioURL;view.voice='speaking';render();await v.player.play()}catch(e){if(voiceSession!==v||v.turn!==turn)return;if(e.name==='AbortError')return;view.voice='idle';view.audioBlocked=e.name==='NotAllowedError';render();if(!view.audioBlocked)toast(tr('Your text reply is ready; audio playback is unavailable.','الرد النصي جاهز، لكن تشغيل الصوت غير متاح.','La réponse écrite est prête ; l’audio est indisponible.'))}}
function stopVoice(){if(voiceSession&&view.requestVoice===voiceSession){view.requestController?.abort();view.requestGeneration=(view.requestGeneration||0)+1;view.busy=false;view.requestVoice=null}voiceGeneration++;view.connecting=false;view.audioBlocked=false;pendingVoiceStream?.getTracks().forEach(t=>t.stop());pendingVoiceStream=null;const v=voiceSession;voiceSession=null;if(v){clearTimeout(v.timer);clearTimeout(v.recordTimer);cancelAnimationFrame(v.levelFrame);v.requestAbort?.abort();v.audioAbort?.abort();if(v.recorder?.state==='recording')v.recorder.stop();v.stream?.getTracks().forEach(t=>t.stop());v.player?.pause();v.player?.remove();if(v.audioURL)URL.revokeObjectURL(v.audioURL);v.ctx?.close().catch(()=>{})}view.voice='idle'}
window.addEventListener('pagehide',stopVoice);

function submitIntake(e){e.preventDefault();const form=$('#intakeform');if(!form.checkValidity()){form.reportValidity();return}const values={};form.querySelectorAll('[data-intake]').forEach(x=>values[x.dataset.intake]=x.value.trim());if(Object.values(values).some(x=>!x)){toast(tr('Please answer before continuing.','يرجى الإجابة للمتابعة.','Répondez avant de continuer.'));return}if(values.ageRange&&!/^(?:[1-9]\d?|1[01]\d|120)$/.test(values.ageRange)&&!(/prefer|not|say|إفصاح|أفضل|préfère|répondre/i.test(values.ageRange))){toast(tr('Enter a valid age or choose not to say.','أدخل عمرًا صحيحًا أو اختر عدم الإفصاح.','Indiquez un âge valide ou choisissez de ne pas répondre.'));return}if(values.moveDetail){values[values.moveStatus==='Moved'?'area':'timeline']=values.moveDetail;delete values.moveDetail}Object.assign(s.profile,values);if(values.name)s.profile.nameConfirmed=true;s.intakeStep=Math.min(6,intakeStep()+1);view.reply='';view.transcript='';save();render()}
async function saveAccountSummary(){try{const r=await fetch('/api/account/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({consent:true,consentVersion:'owner-summary-v1',name:s.profile.name,kind:s.type,sector:s.profile.sector,interests:s.profile.interests})});const d=await r.json();if(!r.ok)throw new Error(d.error||'Save failed');s.ownerSummaryConsent=true;save();return true}catch(e){toast(tr('Account summary was not saved. Retry, or untick the optional box to continue locally.','لم يُحفظ الملخص. حاول مجددًا أو ألغِ الخيار للمتابعة محليًا.','Résumé non enregistré. Réessayez ou décochez pour continuer localement.'));return false}}
function recordAccountEvent(action,itemId=''){if(!s.ownerSummaryConsent)return;fetch('/api/account/event',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({eventId:crypto.randomUUID(),action,itemId})}).then(r=>{if(!r.ok)console.warn('Activity sync unavailable')}).catch(()=>{})}
function basicProfile(){const fields={name:tr('Name','الاسم','Nom'),ageRange:tr('Age (optional)','العمر (اختياري)','Âge (facultatif)'),gender:tr('Gender (optional)','الجنس (اختياري)','Genre (facultatif)'),origin:tr('Coming from','قادم من','Vous venez de'),family:tr('Coming alone, with partner, children or family?','بمفردك أم مع شريك أو أطفال أو الأسرة؟','Seul, en couple, avec enfants ou en famille ?')};const e=modal(tr('A few basics','معلومات أساسية','Quelques informations'),`<form id="basicsform">${Object.entries(fields).map(([k,label])=>`<label class="field">${label}<input data-basic="${k}" maxlength="100" value="${esc(s.profile[k]||'')}"></label>`).join('')}<p class="small muted">${tr('All optional. Age and gender do not determine your interests. Please do not enter children’s names or personal details.','كلها اختيارية. العمر والجنس لا يحددان اهتماماتك. لا تدخل أسماء الأطفال أو بياناتهم الشخصية.','Tout est facultatif. Âge et genre ne déterminent pas vos goûts. Pas de données personnelles des enfants.')}</p><button class="button">${t('save')}</button></form>`);$('#basicsform').onsubmit=ev=>{ev.preventDefault();document.querySelectorAll('[data-basic]').forEach(x=>s.profile[x.dataset.basic]=x.value.trim());s.profile.nameConfirmed=!!s.profile.name;save();e.remove();render()}}
window.addEventListener('keydown',e=>{if((s.screen==='onboard'&&(intakeStep()<4||intakeStep()>=6))||e.code!=='Space'||e.repeat||!['onboard','ask'].includes(s.screen)||document.querySelector('.modal-backdrop')||/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target?.tagName)||e.target?.isContentEditable)return;e.preventDefault();if(voiceSession)beginHold(e);else startVoice()});window.addEventListener('keyup',e=>{if(e.code==='Space'&&voiceSession?.rt?.holding){e.preventDefault();endHold()}});window.addEventListener('blur',()=>{if(voiceSession?.rt?.holding)endHold()});

window.addEventListener('popstate',()=>{cancelJourney();const h=location.hash.slice(1)||'welcome';if(['welcome','story','onboard','ask','discover','together','plan','walk','review'].includes(h)){view.requestController?.abort();view.requestGeneration=(view.requestGeneration||0)+1;view.busy=false;stopVoice();s.screen=h;render()}});
window.addEventListener('keydown',e=>{if(e.key==='Escape')$('#closemodal')?.click()});
